    if (cached) {
      return { ...cached, duplicate: true };
    }

    let lastError: string | undefined;
    let retryCount = 0;
    const maxAttempts = 1 + this.retryPolicy.maxRetries;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
